Gif_Stream* read_gif_stream(Gif_Reader* grr, int read_flags, const char* landmark, Gif_ReadErrorHandler handler) {
    if (!grr || !landmark || !handler) {
        return NULL;
    }

    Gif_Stream* stream = (Gif_Stream*)malloc(sizeof(Gif_Stream));
    if (!stream) {
        handler("Memory allocation failed for Gif_Stream.", landmark);
        return NULL;
    }

    // Validate GIF signature
    if (strncmp(grr->signature, "GIF", 3) != 0) {
        handler("Invalid GIF signature.", landmark);
        free(stream);
        return NULL;
    }

    // Initialize stream
    stream->images = NULL;
    stream->image_count = 0;
    stream->extensions = NULL;
    stream->extension_count = 0;

    // Process image blocks
    while (1) {
        int block_type = read_next_block(grr);
        if (block_type == GIF_BLOCK_TERMINATOR) {
            break;
        } else if (block_type == GIF_BLOCK_IMAGE) {
            Gif_Image* image = process_image_block(grr);
            if (!image) {
                handler("Failed to process image block.", landmark);
                free_gif_stream(stream);
                return NULL;
            }
            // Add image to stream
            stream->images = realloc(stream->images, (stream->image_count + 1) * sizeof(Gif_Image*));
            if (!stream->images) {
                handler("Memory allocation failed for image array.", landmark);
                free_gif_stream(stream);
                return NULL;
            }
            stream->images[stream->image_count++] = image;
        } else if (block_type == GIF_BLOCK_EXTENSION) {
            Gif_Extension* extension = process_extension_block(grr);
            if (!extension) {
                handler("Failed to process extension block.", landmark);
                free_gif_stream(stream);
                return NULL;
            }
            // Add extension to stream
            stream->extensions = realloc(stream->extensions, (stream->extension_count + 1) * sizeof(Gif_Extension*));
            if (!stream->extensions) {
                handler("Memory allocation failed for extension array.", landmark);
                free_gif_stream(stream);
                return NULL;
            }
            stream->extensions[stream->extension_count++] = extension;
        } else {
            handler("Unknown block type encountered.", landmark);
            free_gif_stream(stream);
            return NULL;
        }
    }

    return stream;
}
